test("import rates scenario 2", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-04-05");
  expect(await ui.setRole(pg_uma, "vic", "steward")).toBe(true);
  await ui.setSetting(pg_uma, "clerk-limit", "3.00");
  await ui.setSetting(pg_uma, "floor", "0.50");
  await ui.setSetting(pg_uma, "terms", "7");
  await ui.setSetting(pg_uma, "perm-close", "clerk");
  expect(await ui.setRole(pg_uma, "wes", "viewer")).toBe(true);
  await ui.setSetting(pg_uma, "grace-days", "3");
  await ui.setSetting(pg_uma, "entry-date", "2026-03-05");
  expect(await ui.addHoliday(pg_uma, "2026-03-16")).toBe(true);
  expect(await ui.addHoliday(pg_uma, "2026-04-03")).toBe(true);
  expect(await ui.addVoidReason(pg_uma, "error")).toBe(true);
  expect(await ui.addVoidReason(pg_uma, "dup")).toBe(true);
  await ui.loadSheet(pg_uma, `${sheet}-p`);
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "12.50"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "33.33"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "10.00"})).toBe(true);
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "C"}));
  await ui.loadSheet(pg_uma, sheet);
  await ui.setSetting(pg_uma, "parent", `${sheet}-p`);
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "20.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "10.00"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
  expect(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "A", "contact": " Ada@x "})).toBeNull();
  const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "B"}));
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "B"}));
  expect(await ui.statement(pg_uma, p_ada)).toBe(true);
  expect(await ui.watch(pg_uma, p_ada, true)).toBe(true);
  const c_ben_0 = ui.must(await ui.quickAdd(pg_uma, {"name": "Ben", "amount": "12.50"}, p_ben));
  expect(await ui.importPeople(pg_uma, "Eve,B")).toMatchObject({"added": 1, "updated": 0});
  const p_eve = await ui.personId(pg_uma, "Eve");
  const c_ada_0 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "25.00", "date": "2026-04-02", "note": "n", "tags": "a"}));
  expect(await ui.addAlias(pg_uma, p_ben, " ada ")).toBe(false);
  expect(await ui.statement(pg_uma, p_ben)).toBe(true);
  await ui.refresh(pg_uma);
  expect(await ui.periodAction(pg_uma, "P1", "soft-close")).toBe(true);
  const c_ben_1 = ui.must(await ui.addClaim(pg_uma, p_ben, {"amount": "0.40", "note": "n"}));
  const pg_vic = await ui.userPage(browser, "vic", sheet);
  expect(await ui.transfer(pg_vic, p_eve, `${sheet}-t`)).toBe(true);
  expect(await ui.claimAction(pg_vic, c_ben_1, "open")).toBe(true);
  expect(await ui.claimAction(pg_vic, c_ada_0, "open")).toBe(true);
  const c_ada_1 = ui.must(await ui.addClaim(pg_vic, p_ada, {"amount": "3.33", "date": "2026-04-02"}));
  await ui.refresh(pg_uma);
  expect(await ui.bulkSettle(pg_uma, [c_ada_0, c_ben_1])).toEqual({ settled: 2, refused: 0 });
  await ui.refresh(pg_uma);
  const pg_wes = await ui.userPage(browser, "wes", sheet);
  expect(await ui.claimAction(pg_wes, c_ben_0, "open")).toBe(false);
  expect(await ui.retire(pg_wes, p_ben, "2026-03-01")).toBe(false);
  expect(await ui.addPatron(pg_wes, p_ben, "Ada")).toBe(false);
  expect(await ui.addClaim(pg_wes, p_ben, {"amount": "25.00", "date": "2026-04-02", "note": "n", "tags": " c "})).toBeNull();
  await ui.refresh(pg_vic);
  await ui.setAsOf(pg_vic, "2026-03-20");
  await ui.refresh(pg_vic);

